CREATE TABLE IF NOT EXISTS energy_history_15m (bucket_start DATETIME NOT NULL,signal_name VARCHAR(100) NOT NULL,avg_value DECIMAL(20,6) NOT NULL,min_value DECIMAL(20,6) NOT NULL,max_value DECIMAL(20,6) NOT NULL,sample_count INT UNSIGNED NOT NULL,energy_kwh DECIMAL(20,8) NULL,source VARCHAR(50) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(bucket_start,signal_name),INDEX idx_history_signal_time(signal_name,bucket_start));
